-- charles-trenet.net content database (read-only at runtime).
-- Generated by scripts/migrate/index.ts — do not edit by hand.

CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);

CREATE TABLE themes (
  id INTEGER PRIMARY KEY,           -- legacy topic id
  slug TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  description TEXT NOT NULL,
  position INTEGER NOT NULL
);

CREATE TABLE articles (
  id INTEGER PRIMARY KEY,           -- legacy story id (sid)
  slug TEXT NOT NULL,
  title TEXT NOT NULL,
  legacy_title TEXT NOT NULL,
  theme_id INTEGER REFERENCES themes(id),
  category TEXT,                    -- Références / Témoignages / Sa Route Enchantée
  series TEXT,                      -- e.g. "Les grands moments"
  series_part INTEGER,
  author TEXT,
  published_at TEXT NOT NULL,       -- ISO 8601
  intro_html TEXT NOT NULL,
  body_html TEXT NOT NULL,
  excerpt TEXT NOT NULL,
  cover_url TEXT,
  cover_width INTEGER,
  cover_height INTEGER,
  reading_minutes INTEGER NOT NULL,
  legacy_views INTEGER NOT NULL DEFAULT 0,
  comment_count INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX articles_theme ON articles(theme_id, published_at);
CREATE INDEX articles_date ON articles(published_at);

CREATE TABLE comments (
  id INTEGER PRIMARY KEY,
  article_id INTEGER NOT NULL REFERENCES articles(id),
  parent_id INTEGER,
  author TEXT NOT NULL,
  posted_at TEXT NOT NULL,
  subject TEXT,
  body_html TEXT NOT NULL
);
CREATE INDEX comments_article ON comments(article_id, posted_at);

-- Lyrics, poems, letters and documents (old chansons/*.html pages)
CREATE TABLE texts (
  id INTEGER PRIMARY KEY,
  slug TEXT NOT NULL UNIQUE,
  legacy_file TEXT NOT NULL UNIQUE,
  kind TEXT NOT NULL,               -- chanson | poeme | lettre | document
  title TEXT NOT NULL,
  author TEXT NOT NULL,
  credits TEXT,
  copyright TEXT,
  body_html TEXT NOT NULL,
  plain TEXT NOT NULL
);

-- The A–Z song catalogue
CREATE TABLE songs (
  id INTEGER PRIMARY KEY,
  slug TEXT NOT NULL UNIQUE,
  title TEXT NOT NULL,
  sort_title TEXT NOT NULL,
  letter TEXT NOT NULL,
  year INTEGER,
  publisher TEXT,
  unpublished INTEGER NOT NULL DEFAULT 0,
  performed_only INTEGER NOT NULL DEFAULT 0,
  text_id INTEGER REFERENCES texts(id),
  see_also_id INTEGER REFERENCES songs(id),
  see_also_title TEXT,
  position INTEGER NOT NULL
);
CREATE INDEX songs_letter ON songs(letter, position);
CREATE INDEX songs_text ON songs(text_id);

-- Which articles link to which text
CREATE TABLE text_mentions (
  text_id INTEGER NOT NULL REFERENCES texts(id),
  article_id INTEGER NOT NULL REFERENCES articles(id),
  PRIMARY KEY (text_id, article_id)
) WITHOUT ROWID;

CREATE TABLE timeline (
  id INTEGER PRIMARY KEY,
  start_year INTEGER NOT NULL,
  end_year INTEGER,
  events_html TEXT NOT NULL,
  related_json TEXT NOT NULL
);

CREATE TABLE forums (
  id INTEGER PRIMARY KEY,           -- legacy fid
  slug TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  description TEXT NOT NULL,
  position INTEGER NOT NULL,
  thread_count INTEGER NOT NULL,
  post_count INTEGER NOT NULL,
  first_post_at TEXT,
  last_post_at TEXT
);

CREATE TABLE threads (
  id INTEGER PRIMARY KEY,           -- legacy tid
  forum_id INTEGER NOT NULL REFERENCES forums(id),
  slug TEXT NOT NULL,
  subject TEXT NOT NULL,
  author TEXT NOT NULL,
  created_at TEXT NOT NULL,
  last_post_at TEXT NOT NULL,
  post_count INTEGER NOT NULL,
  legacy_views INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX threads_forum ON threads(forum_id, last_post_at);

CREATE TABLE posts (
  id INTEGER PRIMARY KEY,
  thread_id INTEGER NOT NULL REFERENCES threads(id),
  position INTEGER NOT NULL,
  author TEXT NOT NULL,
  posted_at TEXT NOT NULL,
  body_html TEXT NOT NULL
);
CREATE INDEX posts_thread ON posts(thread_id, position);

CREATE TABLE agenda (
  id INTEGER PRIMARY KEY,
  title TEXT NOT NULL,
  event_date TEXT NOT NULL,
  body_html TEXT NOT NULL,
  url TEXT
);

-- "Ce jour-là": quotes and anniversaries attached to a day of the year
CREATE TABLE ephemerides (
  id INTEGER PRIMARY KEY,
  day INTEGER NOT NULL,
  month INTEGER NOT NULL,
  year INTEGER,
  body_html TEXT NOT NULL
);
CREATE INDEX ephemerides_day ON ephemerides(month, day);

CREATE TABLE link_categories (
  id INTEGER PRIMARY KEY,
  parent_id INTEGER,
  title TEXT NOT NULL,
  description TEXT NOT NULL
);
CREATE TABLE links (
  id INTEGER PRIMARY KEY,
  category_id INTEGER NOT NULL REFERENCES link_categories(id),
  title TEXT NOT NULL,
  url TEXT NOT NULL,
  description TEXT NOT NULL,
  added_at TEXT NOT NULL
);

CREATE TABLE pages (
  slug TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  body_html TEXT NOT NULL
);

CREATE TABLE media (
  url TEXT PRIMARY KEY,
  legacy_path TEXT NOT NULL UNIQUE,
  width INTEGER,
  height INTEGER,
  bytes INTEGER NOT NULL,
  clip TEXT -- clip-path hiding the frame baked into the image, if any (frames.ts)
);

-- Full-text search, accent-insensitive ("theatre" finds "théâtre").
CREATE VIRTUAL TABLE search USING fts5(
  kind UNINDEXED,
  url UNINDEXED,
  title,
  body,
  meta UNINDEXED,
  tokenize = "unicode61 remove_diacritics 2"
);
